using System;using System.Collections;using System.Collections.Generic;using System.Drawing;using System.IO;using System.Linq;using System.Reflection;using System.Security.Cryptography;using System.Text;using System.Threading;using System.Web.Script.Serialization;using System.Windows.Forms;using UsbRecovery;
public static class FolderExportTests
{
    static string project,root,source,destination;static int checks,sequence;
    static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=16*1024*1024};}
    static void Check(bool value,string why){checks++;if(!value)throw new Exception(why);}
    static string Hash(string file){using(var stream=File.OpenRead(file))using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","").ToLowerInvariant();}
    static RecoveredItem Item(string name,string text){string relative=(++sequence).ToString("D4")+".bin",path=Path.Combine(source,relative);File.WriteAllText(path,text,new UTF8Encoding(false));return new RecoveredItem{Name=name,Path=relative,Bytes=new FileInfo(path).Length,Sha256=Hash(path),Method="Synthetic",Category="Документы",Extension=Path.GetExtension(name)};}
    static OriginalLocation Origin(RecoveredItem item,string path,long volume=0,string status="verified_parent_chain"){return new OriginalLocation{Path=path,Status=status,Evidence="synthetic metadata chain",CandidatePath=item.Path,VolumeOffset=volume};}
    static Dictionary<string,object> Manifest(string output){return Json().Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(output,"export-manifest.json"),Encoding.UTF8));}
    static List<Dictionary<string,object>> Records(string output){return ((IEnumerable)Manifest(output)["files"]).Cast<object>().Cast<Dictionary<string,object>>().ToList();}
    static string Target(string output,Dictionary<string,object> row){return RecoveryCatalog.SafeFile(output,Convert.ToString(row["file"]));}
    static string Export(IEnumerable<RecoveredItem> items,CancellationToken token,bool folders=true){try{return (string)typeof(RecoveryCatalog).GetMethod(folders?"ExportFilesPreservingFolders":"ExportFiles",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{source,destination,items,token});}catch(TargetInvocationException error){throw error.InnerException;}}
    static string Export(params RecoveredItem[] items){return Export(items,CancellationToken.None);}
    static void EveryTargetSafe(string output){foreach(var row in Records(output)){string relative=Convert.ToString(row["file"]),file=Target(output,row);Check(relative.IndexOf(':')<0&&!relative.StartsWith("/")&&!relative.StartsWith("\\")&&relative.Split('/').All(x=>x!="."&&x!=".."),"relative output has no traversal or ADS");Check(File.Exists(file)&&Hash(file)==Convert.ToString(row["sha256"]),"published target hash verified");Check(file.Length+8<260,"target and partial suffix fit Windows path limit");}}
    static void AliasesAndVolumes()
    {
        var item=Item("Пирожки.txt","Рецепт бабушки\r\nUnicode 🥟");string before=Hash(Path.Combine(source,item.Path));item.OriginalLocations.Add(Origin(item,"/Семья/Рецепты/Пирожки.txt"));item.OriginalLocations.Add(Origin(item,"/Семья/Пирожки.txt"));item.OriginalLocations.Add(Origin(item,"/Семья/Пирожки.txt"));item.OriginalLocations.Add(Origin(item,"/Семья/Пирожки.txt",4096));item.OriginalLocations.Add(Origin(item,"/Ненадёжный/Пирожки.txt",0,"filesystem_candidate"));
        string output=Export(item);var rows=Records(output);Check(rows.Count==3,"distinct confirmed aliases exported once");Check(rows.Any(x=>Convert.ToString(x["file"])=="Том-0000000000000000/Семья/Рецепты/Пирожки.txt"),"Unicode hierarchy preserved");Check(rows.Any(x=>Convert.ToString(x["file"]).StartsWith("Том-0000000000001000/",StringComparison.Ordinal)),"source volumes separated");Check(rows.All(x=>Convert.ToString(x["exportedPathStatus"])=="verified_parent_chain"),"candidate path not promoted");Check(rows.All(x=>((IEnumerable)x["originalLocations"]).Cast<object>().Count()==5),"all provenance aliases retained");Check(Convert.ToString(Manifest(output)["status"])=="complete"&&(bool)Manifest(output)["preserveFolders"],"hierarchy mode complete manifest");Check(Hash(Path.Combine(source,item.Path))==before,"source unchanged");EveryTargetSafe(output);
        output=Export(new[]{item},CancellationToken.None,false);rows=Records(output);Check(rows.Count==1&&Convert.ToString(rows[0]["file"])=="000001_Пирожки.txt","flat export compatible");Check(!(bool)Manifest(output)["preserveFolders"],"flat mode recorded");Check(typeof(RecoveryCatalog).GetMethod("ExportFiles",BindingFlags.NonPublic|BindingFlags.Static)!=null,"legacy reflection unambiguous");
    }
    static void UnsafeAndUnknown()
    {
        var items=new List<RecoveredItem>();foreach(string path in new[]{"/../outside.txt","/folder/../../outside.txt","//server/share/file.txt","C:\\outside.txt","\\\\?\\C:\\outside.txt","/a//b.txt","/a/./b.txt"}){var item=Item("unsafe.txt","unsafe path "+path);item.OriginalLocations.Add(Origin(item,path));items.Add(item);}
        var unknown=Item("CON.txt","unknown");unknown.OriginalLocations.Add(Origin(unknown,"/candidate.txt",0,"filesystem_candidate"));items.Add(unknown);var proof=Item("proof.txt","missing proof");var origin=Origin(proof,"/unproven/proof.txt");origin.Evidence=null;proof.OriginalLocations.Add(origin);items.Add(proof);var reserved=Item("reserved.txt","device words");reserved.OriginalLocations.Add(Origin(reserved,"/CON/AUX.txt"));items.Add(reserved);var sanitized=Item("literal.txt","<script>no execution</script>");sanitized.OriginalLocations.Add(Origin(sanitized,"/bad<folder>/name?.txt"));items.Add(sanitized);
        string output=Export(items,CancellationToken.None);var rows=Records(output);Check(rows.Count==items.Count,"unsafe paths retain bytes in safe fallback");Check(rows.Where(x=>Convert.ToString(x["source"])!=reserved.Path&&Convert.ToString(x["source"])!=sanitized.Path).All(x=>Convert.ToString(x["file"]).StartsWith("Без подтверждённой папки/",StringComparison.Ordinal)),"traversal drive UNC and unconfirmed paths use fallback");Check(rows.Single(x=>Convert.ToString(x["source"])==reserved.Path)["file"].ToString().Contains("_CON")&&rows.Single(x=>Convert.ToString(x["source"])==reserved.Path)["file"].ToString().Contains("_AUX"),"device names escaped");Check(rows.Single(x=>Convert.ToString(x["source"])==sanitized.Path)["file"].ToString().IndexOfAny(new[]{'<','>','?'})<0,"forbidden characters escaped");EveryTargetSafe(output);Check(!File.Exists(Path.Combine(destination,"outside.txt")),"no escape output");
    }
    static void CollisionsAndLongPaths()
    {
        var a=Item("same.txt","first");var b=Item("same.txt","second");var c=Item("node","file first");var d=Item("child.txt","child");var e=Item("child2.txt","child2");var f=Item("later","folder first");var g=Item("later-child.txt","later child");var h=Item("long.txt","deep");a.OriginalLocations.Add(Origin(a,"/Case/same.txt"));b.OriginalLocations.Add(Origin(b,"/case/SAME.txt"));c.OriginalLocations.Add(Origin(c,"/node"));d.OriginalLocations.Add(Origin(d,"/node/child.txt"));e.OriginalLocations.Add(Origin(e,"/node/child2.txt"));g.OriginalLocations.Add(Origin(g,"/later/child.txt"));f.OriginalLocations.Add(Origin(f,"/later"));h.OriginalLocations.Add(Origin(h,"/"+String.Join("/",Enumerable.Repeat(new string('x',120),20))+"/long.txt"));
        string output=Export(a,b,c,d,e,g,f,h);var rows=Records(output);Check(rows.Count==8&&rows.Select(x=>Convert.ToString(x["file"])).Distinct(StringComparer.OrdinalIgnoreCase).Count()==8,"case file directory collisions never overwrite");Check(rows.Single(x=>Convert.ToString(x["source"])==d.Path)["file"].ToString().Contains("node~папка-"),"file-before-folder has stable directory alias");Check(Path.GetDirectoryName(Target(output,rows.Single(x=>Convert.ToString(x["source"])==d.Path)))==Path.GetDirectoryName(Target(output,rows.Single(x=>Convert.ToString(x["source"])==e.Path))),"later children reuse directory alias");Check(rows.Single(x=>Convert.ToString(x["source"])==h.Path)["file"].ToString().StartsWith("Длинные пути/",StringComparison.Ordinal),"long paths use bounded fallback");Check(rows.Single(x=>Convert.ToString(x["source"])==h.Path)["exportedOriginalPath"].ToString()==h.OriginalLocations[0].Path,"long original kept in manifest");EveryTargetSafe(output);
    }
    static IEnumerable<RecoveredItem> CancelBetween(RecoveredItem first,RecoveredItem second,CancellationTokenSource cancellation){yield return first;cancellation.Cancel();yield return second;}
    static void FailureAndCancellation()
    {
        var first=Item("done.txt","retained");var second=Item("stop.txt","never publish");first.OriginalLocations.Add(Origin(first,"/done.txt"));string[] before=Directory.GetDirectories(destination);bool failed=false;using(var cancellation=new CancellationTokenSource())try{Export(CancelBetween(first,second,cancellation),cancellation.Token);}catch(OperationCanceledException){failed=true;}
        string output=Directory.GetDirectories(destination).Except(before).Single();Check(failed&&Records(output).Count==1&&Convert.ToString(Manifest(output)["status"])=="incomplete","cancel retains finished file with incomplete manifest");Check(!Directory.EnumerateFiles(output,"*.partial",SearchOption.AllDirectories).Any(),"cancel cleans temporary payload");EveryTargetSafe(output);
        before=Directory.GetDirectories(destination);using(var cancellation=new CancellationTokenSource()){cancellation.Cancel();failed=false;try{Export(new[]{first},cancellation.Token);}catch(OperationCanceledException){failed=true;}Check(failed&&Directory.GetDirectories(destination).Length==before.Length,"cancel before start creates no folder");}
        var changed=Item("changed.txt","original");File.AppendAllText(Path.Combine(source,changed.Path)," altered");string sourceHash=Hash(Path.Combine(source,changed.Path));before=Directory.GetDirectories(destination);failed=false;try{Export(changed);}catch(IOException){failed=true;}output=Directory.GetDirectories(destination).Except(before).Single();Check(failed&&Records(output).Count==0&&Convert.ToString(Manifest(output)["status"])=="incomplete","SHA mismatch prevents success");Check(!Directory.EnumerateFiles(output,"*.partial",SearchOption.AllDirectories).Any()&&Hash(Path.Combine(source,changed.Path))==sourceHash,"failed export preserves source and cleans partial");var badSize=Item("bad-size.txt","size checked");badSize.Bytes++;before=Directory.GetDirectories(destination);failed=false;try{Export(badSize);}catch(IOException){failed=true;}output=Directory.GetDirectories(destination).Except(before).Single();Check(failed&&Records(output).Count==0,"size mismatch blocked despite matching hash");failed=false;try{RecoveryCatalog.ExportPreservingFolders(source,source,new[]{first},CancellationToken.None);}catch(IOException){failed=true;}Check(failed,"public export requires separate destination");
    }
    static void Interface()
    {
        RecoveryCore.SaveJson(Path.Combine(source,"files-index.json"),new RecoveryFileIndex());using(var form=new RecoveryFilesForm(source)){form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-20000,-20000);form.ClientSize=new Size(900,650);form.Show();Application.DoEvents();var box=(CheckBox)typeof(RecoveryFilesForm).GetField("preserveFolders",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(form);Check(box.Text=="Сохранить папки"&&!box.Checked&&box.Enabled,"simple folder option defaults opt in");Rectangle area=form.RectangleToClient(box.RectangleToScreen(box.ClientRectangle));Check(box.Visible&&area.Left>=0&&area.Right<=form.ClientSize.Width&&area.Bottom<form.ClientSize.Height,"folder checkbox fits minimum window");box.Checked=true;Check(box.Checked,"folder option is selectable");form.Close();}
    }
    [STAThread]public static int Main(string[] args)
    {
        try{project=Path.GetFullPath(args.Length==0?Directory.GetCurrentDirectory():args[0]);root=Path.Combine(project,".build","folder-export-"+Guid.NewGuid().ToString("N").Substring(0,8));source=Path.Combine(root,"source");destination=Path.Combine(root,"out");Directory.CreateDirectory(source);Directory.CreateDirectory(destination);Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);AliasesAndVolumes();UnsafeAndUnknown();CollisionsAndLongPaths();FailureAndCancellation();Interface();string summary="PASS FolderExport: "+checks+" assertions; confirmed aliases/volumes, safe Windows paths, collisions, flat compatibility, SHA/size failures, cancellation, minimum-size UI. Synthetic local files only. "+root;Console.WriteLine(summary);File.WriteAllText(Path.Combine(project,"tests","FolderExportTests.result.txt"),summary,new UTF8Encoding(false));return 0;}catch(Exception error){Console.Error.WriteLine(error);return 1;}
    }
}
